<?php if ($findings === []): ?><div class="ios-card empty-state"><span class="empty-icon"><?= icon('clipboard', 'h-7 w-7') ?></span><h3>No hay hallazgos en esta vista</h3><p>Registra una oportunidad de mejora para iniciar su seguimiento.</p></div><?php else: ?><div class="space-y-4"><?php foreach ($findings as $finding): ?><article class="ios-card p-5 sm:p-6"><div class="flex flex-col gap-4 lg:flex-row lg:items-start"><div class="flex min-w-0 flex-1 items-start gap-4"><span class="metric-icon shrink-0 <?= $finding['estado'] === 'Cerrado' ? 'bg-emerald-50 text-emerald-600' : 'bg-amber-50 text-amber-600' ?>"><?= icon($finding['estado'] === 'Cerrado' ? 'check-circle' : 'alert', 'h-5 w-5') ?></span><div class="min-w-0"><div class="flex flex-wrap items-center gap-2"><span class="badge badge-gray"><?= e($finding['origen']) ?></span><span class="badge <?= status_class($finding['estado']) ?>"><?= e($finding['estado']) ?></span><?php if (is_overdue($finding)): ?><span class="badge badge-red">Vencido</span><?php endif; ?><span class="text-[10px] text-slate-400">#<?= (int) $finding['id'] ?></span></div><p class="mt-3 text-sm font-medium leading-6 text-slate-700"><?= e($finding['descripcion']) ?></p><div class="mt-4 rounded-2xl bg-blue-50/70 p-4"><p class="text-[10px] font-bold uppercase tracking-wider text-blue-500">Acción correctiva</p><p class="mt-2 text-xs leading-6 text-blue-950/75"><?= e($finding['accion_correctiva']) ?></p></div></div></div><div class="shrink-0 lg:w-56"><dl class="grid grid-cols-2 gap-3 text-xs lg:grid-cols-1"><div><dt class="text-[10px] text-slate-400">Responsable</dt><dd class="mt-1 font-medium text-slate-700"><?= e($finding['responsable']) ?></dd></div><div><dt class="text-[10px] text-slate-400">Fecha límite</dt><dd class="mt-1 font-medium <?= is_overdue($finding) ? 'text-rose-600' : 'text-slate-700' ?>"><?= format_date($finding['fecha_limite']) ?></dd></div><?php if ($finding['fecha_cierre']): ?><div><dt class="text-[10px] text-slate-400">Cerrado</dt><dd class="mt-1 font-medium text-emerald-600"><?= format_date($finding['fecha_cierre']) ?></dd></div><?php endif; ?></dl><div class="mt-4 flex gap-2"><a href="<?= e(url('/hallazgos/' . $finding['id'] . '/editar')) ?>" class="btn-secondary flex-1"><?= icon('edit', 'h-4 w-4') ?> Editar</a><form method="post" action="<?= e(url('/hallazgos/' . $finding['id'] . '/eliminar')) ?>" data-confirm="¿Eliminar este hallazgo y su acción? La acción quedará auditada."><?= csrf_field() ?><button type="submit" class="btn-danger-soft">Eliminar</button></form></div><form method="post" action="<?= e(url('/hallazgos/' . $finding['id'] . '/estado')) ?>" class="mt-3" data-confirm="<?= $finding['estado'] === 'Abierto' ? '¿Cerrar este hallazgo? Confirma que la acción fue implementada y que conservas evidencia de su eficacia.' : '¿Reabrir este hallazgo para continuar su seguimiento?' ?>"><?= csrf_field() ?><input type="hidden" name="estado" value="<?= $finding['estado'] === 'Abierto' ? 'Cerrado' : 'Abierto' ?>"><button type="submit" class="<?= $finding['estado'] === 'Abierto' ? 'btn-primary' : 'btn-secondary' ?> w-full"><?= icon($finding['estado'] === 'Abierto' ? 'check' : 'phva', 'h-4 w-4') ?><?= $finding['estado'] === 'Abierto' ? 'Marcar como cerrado' : 'Reabrir hallazgo' ?></button></form></div></div></article><?php endforeach; ?></div><?php endif; ?></section>
<details id="nuevo-hallazgo" class="ios-card mt-6 overflow-hidden"<?= $errors !== [] ? ' open' : '' ?>><summary class="cursor-pointer list-none p-5"><div class="section-heading"><span class="section-icon"><?= icon('plus', 'h-5 w-5') ?></span><div><h2>Registrar hallazgo y acción correctiva</h2><p>Define una acción que aborde la causa y permita verificar su eficacia.</p></div></div></summary><form method="post" action="<?= e(url('/hallazgos')) ?>" class="grid gap-5 border-t border-slate-100 p-5 sm:grid-cols-2"><?= csrf_field() ?><div><label class="label">Origen *</label><select name="origen" class="input"><?php foreach (['Auditoria','Inspeccion','Accidente','Reporte'] as $origin): ?><option<?= selected(old('origen'), $origin) ?>><?= $origin ?></option><?php endforeach; ?></select></div><div><label class="label">Responsable *</label><input name="responsable" class="input" value="<?= e(old('responsable')) ?>" required><?= field_error('responsable') ?></div><div class="sm:col-span-2"><label class="label">Descripción del hallazgo *</label><textarea name="descripcion" class="input min-h-24" required><?= e(old('descripcion')) ?></textarea><?= field_error('descripcion') ?></div><div class="sm:col-span-2"><label class="label">Acción correctiva *</label><textarea name="accion_correctiva" class="input min-h-24" placeholder="Qué se hará, cómo se abordará la causa y qué evidencia se espera" required><?= e(old('accion_correctiva')) ?></textarea><?= field_error('accion_correctiva') ?></div><div><label class="label">Fecha límite *</label><input name="fecha_limite" type="date" class="input" value="<?= e(old('fecha_limite', date('Y-m-d', strtotime('+30 days')))) ?>" required><?= field_error('fecha_limite') ?></div><div class="flex items-end justify-end"><button type="submit" class="btn-primary">Guardar hallazgo</button></div></form></details>
